"""
Development-only simulation, for checking the whole app flow without the ring, earbud or phone sensor.

Enable it by starting the backend with the environment variable RELAXATION_DEV_SIM=1.
Nothing here runs otherwise.

When enabled:
  * the stress readings (fusion engine + phenotyping) are generated by a simple scenario instead of
    being read from Firebase, so the app's 2-second poll sees a moving stress signal;
  * everything the backend would normally WRITE to Firebase (bandit state, policy state, outcomes,
    ratings, baseline, closed-loop state) is kept in memory instead, so real user data is never touched;
  * POST /dev/sim switches the scenario while the app is running.

Scenarios
  normal      stress settles near 0.15
  stress      stress rises quickly to about 0.82 (physio) / 0.68 (phone behaviour)
  recovering  stress falls toward the baseline faster than natural recovery would (technique "works")
  slow        stress falls slowly, like natural recovery (technique "does little")
  flat        stress stays where it is (technique "does not work" -> switch banner)
"""

import math
import time
from typing import Any, Dict, Optional

import numpy as np

BASELINE = 0.30
SCENARIOS = {
    #            target(physio)  time constant seconds
    "normal":     (0.15, 25.0),
    "stress":     (0.82, 20.0),
    "recovering": (BASELINE, 70.0),
    "slow":       (BASELINE, 600.0),
    "flat":       (None, 1.0),
}


def _label(p: float) -> str:
    return "stress" if p >= 0.60 else "pre-stress" if p >= 0.35 else "normal"


class DevSimulation:
    def __init__(self) -> None:
        self.scenario = "stress"
        self.physio = 0.20
        self.pheno = 0.20
        self._t = time.time()
        self.rng = np.random.default_rng(11)

    def set_scenario(self, name: str) -> None:
        if name not in SCENARIOS:
            raise ValueError(f"unknown scenario '{name}'")
        self.scenario = name

    def _advance(self) -> None:
        now = time.time()
        dt = max(0.0, min(30.0, now - self._t))
        self._t = now
        target, tau = SCENARIOS[self.scenario]
        if target is not None and dt > 0:
            k = 1.0 - math.exp(-dt / tau)
            self.physio += (target - self.physio) * k
            pheno_target = target if self.scenario != "stress" else 0.68
            self.pheno += (pheno_target - self.pheno) * (1.0 - math.exp(-dt / (tau * 1.5)))

    def _noisy(self, level: float) -> float:
        return float(np.clip(level + self.rng.normal(0, 0.012), 0.02, 0.98))

    def fusion(self) -> Dict[str, Any]:
        self._advance()
        reading = self._noisy(self.physio)
        return {
            "fused_stress_label": _label(reading),
            "stress_probability": reading,
            "is_calibrated": True,
            "has_live_packet": True,
            "active_session_id": "dev-sim",
            "raw_label": _label(reading),
            "user_baseline": BASELINE,
        }

    def phenotyping(self) -> Dict[str, Any]:
        reading = self._noisy(self.pheno)
        return {
            "label": _label(reading),
            "stress_score": reading,
            "has_live_packet": True,
            "active_session_id": "dev-sim",
        }


def install(app, firebase_service, telemetry_aggregator) -> DevSimulation:
    sim = DevSimulation()
    memory: Dict[str, Dict[str, Any]] = {
        "bandit": {}, "policy": {}, "closed_loop": {}, "ratings": {}, "interventions": {},
    }

    # --- stress readings come from the scenario ---
    telemetry_aggregator.read_fusion_engine_output = lambda user_id, session_id=None: sim.fusion()
    firebase_service.get_latest_phenotyping_prediction = lambda user_id: sim.phenotyping()
    firebase_service.get_baseline = lambda user_id, session_id=None: BASELINE
    firebase_service.baseline_exists = lambda user_id: True

    # --- nothing is written to Firebase; state lives in memory for this run ---
    firebase_service.save_baseline = lambda *a, **k: True
    firebase_service.save_intervention_session = lambda *a, **k: None
    firebase_service.get_fastest_recovery_technique_history = lambda user_id: {}

    firebase_service.save_bandit_distribution = lambda user_id, cluster_id, technique_id, alpha, beta: (
        memory["bandit"].setdefault(user_id, {}).setdefault(int(cluster_id), {}).__setitem__(
            technique_id, {"alpha": float(alpha), "beta": float(beta)}))
    firebase_service.get_bandit_distributions = lambda user_id: memory["bandit"].get(user_id, {})
    firebase_service.save_policy_state = lambda user_id, state: memory["policy"].__setitem__(user_id, state)
    firebase_service.get_policy_state = lambda user_id: memory["policy"].get(user_id)
    firebase_service.save_closed_loop_state = lambda user_id, state: memory["closed_loop"].__setitem__(user_id, state)
    firebase_service.get_closed_loop_state = lambda user_id: memory["closed_loop"].get(user_id)
    firebase_service.save_rating = lambda user_id, technique_id, sub_option_id, stars, timestamp: (
        memory["ratings"].setdefault(user_id, []).append(
            {"technique_id": technique_id, "sub_option_id": sub_option_id, "stars": stars, "timestamp": timestamp}))
    firebase_service.get_ratings = lambda user_id: memory["ratings"].get(user_id, [])
    firebase_service.save_relaxation_intervention = lambda user_id, session_id, data: (
        memory["interventions"].setdefault(user_id, []).append(data))
    firebase_service.get_relaxation_interventions = lambda user_id: memory["interventions"].get(user_id, [])

    # --- scenario control ---
    from flask import jsonify, request

    def dev_sim():
        if request.method == "POST":
            data = request.get_json(silent=True) or {}
            try:
                sim.set_scenario(str(data.get("scenario", "stress")))
            except ValueError as e:
                return jsonify({"error": str(e), "scenarios": list(SCENARIOS)}), 400
        return jsonify({
            "scenario": sim.scenario,
            "physio": round(sim.physio, 3),
            "pheno": round(sim.pheno, 3),
            "baseline": BASELINE,
            "scenarios": list(SCENARIOS),
            "note": "DEV SIMULATION: readings are generated and nothing is written to Firebase.",
        }), 200

    app.add_url_rule("/dev/sim", "dev_sim", dev_sim, methods=["GET", "POST"])
    print("[DEV SIM] Simulated stress readings enabled; Firebase writes disabled. "
          "Switch scenario: POST /dev/sim {\"scenario\": \"normal|stress|recovering|slow|flat\"}")
    return sim
